package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

// realClock uses the system time.
type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// SystemClock is the production Clock.
var SystemClock Clock = realClock{}

// Limiter is a concurrency-safe token-bucket rate limiter.
// It is safe for concurrent use by multiple goroutines.
type Limiter struct {
	mu        sync.Mutex
	rate      float64   // tokens per second
	burst     float64   // bucket capacity
	tokens    float64   // current tokens
	last      time.Time // last refill time
	clock     Clock
}

// New creates a Limiter with the given refill rate (tokens per second)
// and burst capacity. rate must be > 0 and burst must be >= 1.
func New(rate float64, burst int) (*Limiter, error) {
	return NewWithClock(rate, burst, SystemClock)
}

// NewWithClock is New with an injectable Clock.
func NewWithClock(rate float64, burst int, clock Clock) (*Limiter, error) {
	if rate <= 0 {
		return nil, errors.New("ratelimit: rate must be > 0")
	}
	if burst < 1 {
		return nil, errors.New("ratelimit: burst must be >= 1")
	}
	if clock == nil {
		return nil, errors.New("ratelimit: clock must not be nil")
	}
	return &Limiter{
		rate:   rate,
		burst:  float64(burst),
		tokens: float64(burst),
		last:   clock.Now(),
		clock:  clock,
	}, nil
}

// Allow reports whether a single token is available.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens are available at the current time,
// consuming them if so. n must be >= 1; AllowN returns false for n <= 0.
func (l *Limiter) AllowN(n int) bool {
	if n <= 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens = min(l.burst, l.tokens+elapsed*l.rate)
		l.last = now
	}
	if l.tokens < float64(n) {
		return false
	}
	l.tokens -= float64(n)
	return true
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
